window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/humanas_2024.js"]=[{"title":"Distância da subducção e intensidade sísmica","steps":["Localize o Chile na borda convergente entre Nazca e a placa Sul-Americana.","A subducção acumula tensões e produz terremotos; seus efeitos podem alcançar o interior continental.","São Paulo está mais distante desse limite que o Chile. O critério comparativo é a posição em relação às zonas de subducção, C."],"alternatives":{"A":"Planícies são formas de relevo, não o limite tectônico que explica os abalos.","B":"Bacias sedimentares não constituem a origem comum dos três eventos relatados.","C":"A distância das zonas de subducção diferencia a exposição aos eventos tectônicos.","D":"Denudação é desgaste do relevo, não a liberação de energia no interior da Terra.","E":"Vertentes escarpadas podem sofrer deslizamentos, mas não explicam a origem dos sismos."},"takeaway":"Não confunda processos internos, como tectonismo, com a modelagem externa do relevo.","key":"humanas:H522","area":"humanas","year":2024,"number":46,"answer":"C","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A metáfora do exército na saúde pública","steps":["Observe a oposição entre oficiais e auxiliares na abertura do texto.","Os autores distribuem funções entre técnicos graduados, enfermeiras, inspetores e pessoal burocrático.","A metáfora apresenta uma organização escalonada do trabalho, isto é, hierarquização profissional, E."],"alternatives":{"A":"O texto não atribui doenças a vícios morais nem propõe moralização dos costumes.","B":"Não há proposta de seleção biológica ou racial que caracterizaria eugenia.","C":"As funções sanitárias não são apresentadas como assimilação de outra cultura.","D":"O trecho diferencia tarefas e posições, não impõe uma identidade nacional única.","E":"A relação entre graduados e auxiliares expressa níveis de responsabilidade profissional."},"takeaway":"Identifique o que uma comparação organiza: neste caso, posições e funções de trabalho.","key":"humanas:H081","area":"humanas","year":2024,"number":47,"answer":"E","subject":"História do Brasil","topic":"Primeira República","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O desastre e o espaço vivido","steps":["O relato destaca sonhos, histórias familiares e objetos abandonados.","Espaço vivido envolve pertencimento e relações afetivas, não apenas localização física.","A destruição das localidades rompe esses laços com lugares de memória: fragilização de vínculos afetivos, C."],"alternatives":{"A":"Não se discutem mudanças legais nos parâmetros de proteção ambiental.","B":"A perda traumática dos lugares não é apresentada como consolidação de identidades.","C":"A lama destrói referências materiais de vidas e memórias, fragilizando vínculos.","D":"O rompimento não prova que a mineração ou outras práticas exploratórias cessaram.","E":"O abandono dos locais não corresponde à recuperação de tradições ancestrais."},"takeaway":"Em questões sobre lugar, procure experiências, memórias e pertencimento no enunciado.","key":"humanas:H267","area":"humanas","year":2024,"number":48,"answer":"C","subject":"Geografia","topic":"Meio ambiente e problemas ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Tecnologia como símbolo da República","steps":["Situe os inventos no final do século XIX e início do XX.","A nova ordem republicana associava modernização material, ciência e progresso à imagem de nação.","A eletrificação e os transportes aparecem como sinais desse projeto republicano, E, não como retorno a estruturas antigas."],"alternatives":{"A":"A circulação de inventos não é descrita como estratégia brasileira de expansão imperialista.","B":"Mercantilismo pertence a outra configuração histórica; não explica a política republicana citada.","C":"Embora o Estado republicano se secularize, o trecho não trata do ensino laico.","D":"Absolutismo é incompatível com a associação política entre progresso e República.","E":"As novidades técnicas eram mobilizadas como demonstração de uma nação republicana moderna."},"takeaway":"Relacione inovação técnica ao projeto político da época, sem tratá-la como processo neutro.","key":"humanas:H082","area":"humanas","year":2024,"number":49,"answer":"E","subject":"História do Brasil","topic":"Primeira República","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[20],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um defensor visto por grupos opostos","steps":["Separe quem depende do trabalho indígena compulsório de quem sofre essa exploração.","Os senhores o odeiam porque sua intervenção ameaça os braços das minas e lavouras.","Os explorados o valorizam como defensor: detestado pelos colonizadores e respeitado pelos povos do lugar, B."],"alternatives":{"A":"O imperador promulga leis favoráveis à intervenção; o contraste não é reis versus religiosos.","B":"A alternativa identifica corretamente interesses coloniais e a defesa dos povos explorados.","C":"Não há oposição entre a colônia inteira e governantes que o idolatrariam.","D":"A metrópole não aparece unicamente como sua adversária; e invasores não são os beneficiados.","E":"Inverte os polos: os excluídos são defendidos, não os que o desacatam no relato."},"takeaway":"Em textos de perspectivas contrastantes, nomeie cada grupo antes de procurar a alternativa.","key":"humanas:H190","area":"humanas","year":2024,"number":50,"answer":"B","subject":"História Geral","topic":"Idade Moderna: Renascimento, Reforma e absolutismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A origem popular da dança e a distinção social","steps":["O comando delimita o início da Idade Moderna, não toda a história da valsa.","A aristocracia francesa a abandona pela proximidade com a cultura plebeia.","A rejeição decorre de elementos provenientes de segmentos populares, E; o texto não atribui a decisão a rituais religiosos."],"alternatives":{"A":"A narrativa não associa a dança à feitiçaria nórdica.","B":"Não apresenta rituais pagãos como motivo da rejeição aristocrática moderna.","C":"A razão mencionada não são regras criadas pelo Renascimento, mas a origem social.","D":"Não relaciona o ritmo a territórios colonizados ou a uma rejeição colonial.","E":"A relação com danças campestres e cultura plebeia fundamenta o distanciamento da elite."},"takeaway":"Use o recorte temporal do comando para não responder com outra passagem do texto.","key":"humanas:H261","area":"humanas","year":2024,"number":51,"answer":"E","subject":"História Geral","topic":"Cultura, memória e conhecimento histórico","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma identidade que inclui diferenças internas","steps":["O movimento critica o nacionalismo estreito e o protagonismo exclusivo de homens heterossexuais.","Em seguida enumera mulheres, pessoas LGBTQIA+, com deficiência e em outras situações de vulnerabilidade.","A reivindicação é integrar a diversidade do grupo identitário, B, e não estabelecer uma única forma legítima de ser negro."],"alternatives":{"A":"Manter direitos já conquistados é genérico e não explica a inclusão interna destacada.","B":"A enumeração amplia quem é reconhecido e representado dentro da comunidade negra.","C":"A ênfase não está em preservar tradições africanas, mas em acolher diferenças atuais.","D":"Valores supremacistas contradizem a defesa de vidas historicamente marginalizadas.","E":"O modelo androcêntrico é criticado, não reivindicado pelo movimento descrito."},"takeaway":"Uma categoria identitária pode conter desigualdades de gênero, sexualidade e outras experiências.","key":"humanas:H730","area":"humanas","year":2024,"number":52,"answer":"B","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Ler velocidade e duração da inundação","steps":["O gráfico mostra pico alto e duração curta na inundação brusca; na gradual, pico menor e duração longa.","Relevos mais inclinados favorecem escoamento rápido; áreas de menor declividade tendem a escoamentos mais lentos.","Entre as opções, a declividade local explica diretamente a diferença hidrológica, C."],"alternatives":{"A":"A variabilidade solar anual não explica diretamente a comparação entre escoamentos locais.","B":"Temperatura média mensal não é o fator de relevo que controla a rapidez indicada.","C":"A inclinação do terreno altera o escoamento e ajuda a distinguir cheias bruscas e graduais.","D":"Tectonismo pode formar relevos em outra escala temporal, mas não é o controle direto cobrado.","E":"Turbidez mede material em suspensão; não é a causa principal da diferença do gráfico."},"takeaway":"Leia os dois eixos e procure um mecanismo físico compatível com ambos.","key":"humanas:H523","area":"humanas","year":2024,"number":53,"answer":"C","subject":"Geografia","topic":"Geologia, relevo e solos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[21],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Preconceito que diminui a credibilidade","steps":["O problema não é a falsidade demonstrada de um depoimento.","A pessoa recebe menos confiança por sua identidade racial ou de gênero.","Isso prejudica sua participação nas trocas de conhecimento e informação: injustiça epistêmica, D."],"alternatives":{"A":"O texto não se concentra em padrões de beleza ou avaliação dos corpos.","B":"Não compara capacidades visuais nem estabelece uma hierarquia entre sentidos.","C":"O núcleo não é impedir emoções, mas desautorizar o que alguém afirma saber.","D":"A identidade reduz injustamente a credibilidade do testemunho nas relações de conhecimento.","E":"Desigualdades materiais podem relacionar-se ao problema, mas não nomeiam a injustiça descrita."},"takeaway":"Epistêmico remete ao conhecimento: quem pode falar, ser ouvido e reconhecido como fonte.","key":"humanas:H692","area":"humanas","year":2024,"number":54,"answer":"D","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A oposição entre corpo e alma","steps":["A voz do texto descreve a alma alojada no corpo, mas capaz de dele escapar.","Também contrapõe a sobrevivência da alma ao apodrecimento corporal.","A separação em dois polos caracteriza pensamento dicotômico, B. Não é necessário atribuir toda a filosofia de Foucault à posição citada."],"alternatives":{"A":"Pressuposto lógico é amplo demais e não identifica a oposição central do trecho.","B":"A distinção alma/corpo organiza a concepção metafísica apresentada.","C":"O trecho não propõe estudar a natureza externa como caminho contemplativo.","D":"Há linguagem reflexiva, mas o comando pede a concepção clássica, não a forma argumentativa.","E":"A individualidade não é o alvo explícito da oposição entre alma duradoura e corpo perecível."},"takeaway":"Analise a concepção expressa no excerto sem supor que ela resume toda a obra do autor.","key":"humanas:H693","area":"humanas","year":2024,"number":55,"answer":"B","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Rito, ancestralidade e memória","steps":["A sequência de gestos coletivos integra a morte a símbolos partilhados.","O ritual reitera saberes e práticas transmitidos entre membros da comunidade.","Para seus adeptos, isso mantém memória coletiva, A, e não nega sua identidade."],"alternatives":{"A":"Gestos repetidos, objetos e participantes atualizam referências coletivas e ancestrais.","B":"O rito fortalece pertencimento; não aparece como rejeição da identidade do grupo.","C":"O falecido é representado por objetos e folhas; não há sacrifício de uma divindade.","D":"Chamar a prática de pagã aplica uma classificação externa, não explica seu sentido para adeptos.","E":"Não se anuncia uma revolta social ou um projeto de insurreição."},"takeaway":"Interprete práticas culturais pelo significado que têm para seus participantes.","key":"humanas:H780","area":"humanas","year":2024,"number":56,"answer":"A","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conflito público e democracia","steps":["O texto rejeita a ideia de que espaços públicos produzam consenso perfeito.","Sua função é tornar problemas e oposições visíveis e permitir diálogo e compromissos.","Essa negociação pública de conflitos contribui para construir democracia, D."],"alternatives":{"A":"O lazer pode ocorrer nesses espaços, mas não é a função política destacada.","B":"A visibilidade de conflitos não equivale a vigilância e controle da sociedade.","C":"O autor não promete eliminar a violência ou os conflitos de maneira definitiva.","D":"Debate, comunicação e possibilidade de acordos são componentes da vida democrática.","E":"O texto não discute ampliação de ocupações ou divisão profissional do trabalho."},"takeaway":"Democracia não é ausência de conflito: envolve meios públicos para enfrentá-lo.","key":"humanas:H393","area":"humanas","year":2024,"number":57,"answer":"D","subject":"Geografia","topic":"Urbanização e espaço urbano","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[22],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Virtude como prática de agir bem","steps":["O primeiro texto associa excelência ao desenvolvimento das melhores disposições humanas.","O segundo define felicidade como atividade vinculada à virtude e à prudência.","O ponto comum é aperfeiçoar condutas humanas na vida em comunidade, D, não possuir apenas conhecimento teórico."],"alternatives":{"A":"Teoria das formas essenciais remete a outro enquadramento, não à prática aristotélica citada.","B":"A razão participa da deliberação, mas identificar princípios abstratos não resume agir virtuosamente.","C":"Habilidade de persuadir não garante virtude moral ou uma escolha prudente.","D":"O aprimoramento habitual e deliberado da ação expressa o vínculo entre virtude e felicidade.","E":"Conhecimentos teóricos verdadeiros não substituem a dimensão prática da ética."},"takeaway":"Em ética aristotélica, diferencie saber sobre o bem de agir bem com prudência.","key":"humanas:H643","area":"humanas","year":2024,"number":58,"answer":"D","subject":"Filosofia","topic":"Filosofia antiga","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Universidade medieval como patrimônio","steps":["O autor reconhece instituições intelectuais duradouras surgidas na Idade Média.","Universidades preservam e organizam tradições de estudo e produzem conhecimento.","O patrimônio destacado agrega tradição e conhecimento científico, E; isso não autoriza dizer que tinham a mesma ciência experimental atual."],"alternatives":{"A":"Padronização curricular não é o fundamento do valor cultural atribuído no trecho.","B":"Não se define o legado pela rejeição a conhecimentos ou costumes orientais.","C":"A universidade não é apresentada como instituição cuja finalidade principal é mercantil.","D":"O texto não reduz sua contribuição a técnicas e valores religiosos ecumênicos.","E":"A continuidade institucional e a produção intelectual explicam o patrimônio reconhecido."},"takeaway":"Evite o estereótipo de uma Idade Média sem vida intelectual e também anacronismos sobre ciência.","key":"humanas:H170","area":"humanas","year":2024,"number":59,"answer":"E","subject":"História Geral","topic":"Idade Média","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Gestão que parte do território","steps":["Os seringueiros transformam uma luta concreta em proposta de reserva extrativista.","O modelo articula modos de vida, saberes e produtividade ecológica de seus territórios.","A nova racionalidade nasce da conexão de valores e decisões locais, B, não de regras impostas de fora."],"alternatives":{"A":"O objetivo apresentado não é submeter territórios às pressões competitivas de mercados.","B":"Decisões locais articulam cultura, condições ecológicas e formas de produzir.","C":"Unificar preços nacionalmente não explica a invenção de reservas extrativistas.","D":"Instituições mundiais não são apresentadas como autoras dessa experiência territorial.","E":"A valorização da tradição parte dos sujeitos locais, e não de determinações globais."},"takeaway":"Em sustentabilidade, pergunte quem decide sobre o território e com quais conhecimentos.","key":"humanas:H268","area":"humanas","year":2024,"number":60,"answer":"B","subject":"Geografia","topic":"Meio ambiente e problemas ambientais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Fazer planos diante da finitude","steps":["A personagem reconhece que não envelhecerá e que certas experiências não voltarão.","Lembrar e imaginar contrastam com a impossibilidade de realizar novos projetos.","O problema filosófico central é a finitude humana, B, e os limites temporais da existência."],"alternatives":{"A":"Não está julgando uma ação como moralmente certa ou errada.","B":"A morte limita o futuro possível e dá sentido à reflexão sobre o que não viverá.","C":"A personagem consegue comunicar a experiência; a linguagem não é o limite investigado.","D":"A opção é genérica e não nomeia o tema específico da mortalidade e do futuro interrompido.","E":"Não se discute como garantir objetividade de enunciados ou de pesquisas."},"takeaway":"Procure o problema preciso do excerto, não apenas uma palavra ampla ligada à filosofia.","key":"humanas:H694","area":"humanas","year":2024,"number":61,"answer":"B","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[23],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Linguagem e critérios de conhecimento","steps":["Carnap distingue enunciados significativos pela relação com conteúdo factual e experiência.","Quine questiona dogmas como a separação analítico/sintético e o reducionismo empirista.","A divergência diz respeito ao estatuto epistemológico da linguagem: como enunciados significam e sustentam conhecimento, A."],"alternatives":{"A":"As posições diferem quanto às condições de significado e conhecimento dos enunciados.","B":"Os trechos não discutem o fundamento de deveres ou juízos morais.","C":"A metafísica aparece no horizonte, mas o contraste explícito trata de enunciados e experiência.","D":"Não se procura um princípio que constitua o ser, e sim critérios de validade cognitiva.","E":"Não há avaliação de beleza, arte ou experiência estética nos argumentos."},"takeaway":"Distingua epistemologia, ontologia e ética pelo tipo de pergunta, não pelo prestígio do termo.","key":"humanas:H664","area":"humanas","year":2024,"number":62,"answer":"A","subject":"Filosofia","topic":"Filosofia moderna: razão, ciência e conhecimento","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A falsa individualidade da indústria cultural","steps":["O trecho afirma que a promessa de liberdade esconde tratamento homogêneo.","A reflexão crítica é substituída pela adesão a produtos e padrões massificados.","O conceito denuncia um mecanismo de controle social, B, não uma simples forma jurídica de empresa."],"alternatives":{"A":"O conceito denuncia a limitação da autonomia, não é apresentado como organização de uma luta.","B":"A padronização e a ilusão de escolha favorecem conformidade e controle social.","C":"Interesse público não descreve a manipulação e a homogeneização criticadas.","D":"Ser iniciativa privada pode caracterizar empresas, mas não define a consequência sociológica.","E":"O controle não é atribuído exclusivamente ao Estado no trecho apresentado."},"takeaway":"Em indústria cultural, relacione mercantilização, padronização e enfraquecimento da crítica.","key":"humanas:H841","area":"humanas","year":2024,"number":63,"answer":"B","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Arte e luta pelo fim da escravidão","steps":["Chiquinha Gonzaga atua explicitamente pelo fim da escravatura.","Os poemas de Castro Alves são identificados como antiescravistas.","A participação comum situa ambos no movimento abolicionista, C, independentemente da diferença de linguagens artísticas."],"alternatives":{"A":"Integralismo é um movimento posterior e não corresponde à luta descrita.","B":"Castro Alves é ligado ao Romantismo; a coincidência dos textos não é filiação realista.","C":"Os dois exemplos articulam produção cultural e defesa da abolição da escravidão.","D":"O foco são pessoas escravizadas e sua libertação, não uma política voltada aos povos indígenas.","E":"O projeto econômico desenvolvimentista pertence a outro debate e não aparece nos textos."},"takeaway":"Não confunda a escola artística de um autor com a causa política destacada no comando.","key":"humanas:H037","area":"humanas","year":2024,"number":64,"answer":"C","subject":"História do Brasil","topic":"Escravidão, abolição e resistências","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Identidades menos fechadas","steps":["Hall descreve identidades plurais, políticas e menos fixas.","Isso abre espaço para experiências que não cabiam numa identidade nacional única.","O efeito compatível é fortalecer pautas de minorias, D; diversidade não significa que desigualdades já acabaram."],"alternatives":{"A":"A passagem não estabelece aumento de renda como consequência desse processo.","B":"Pluralização cultural não equivale a ausência ou abandono de valores morais.","C":"Reconhecer identidades não garante que a igualdade racial tenha sido alcançada.","D":"Identidades plurais permitem maior visibilidade e afirmação de grupos antes marginalizados.","E":"A discussão não permite concluir que se inverteram trajetórias migratórias."},"takeaway":"Diferencie abertura a reivindicações da realização completa dos direitos reivindicados.","key":"humanas:H781","area":"humanas","year":2024,"number":65,"answer":"D","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[24],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Contracepção e planejamento familiar","steps":["A pílula amplia possibilidades de regulação da fecundidade.","Sua difusão ocorre em meio a discussões demográficas e à modernização.","O efeito social pedido é ampliar o debate público sobre planejamento familiar, C, sem supor desaparecimento da medicina ou da religião."],"alternatives":{"A":"A participação médica não desaparece com um método ligado à indústria farmacêutica.","B":"O texto não atribui à mídia estatal a superação dos debates morais.","C":"Um novo método contraceptivo amplia a discussão sobre decisões reprodutivas e família.","D":"Não se demonstra centralização de toda a pesquisa pelo sistema privado de saúde.","E":"Não há base para tomar o endurecimento religioso como o efeito central indicado."},"takeaway":"Tecnologia contraceptiva envolve decisões sociais e direitos, não apenas eficácia biológica.","key":"humanas:H485","area":"humanas","year":2024,"number":66,"answer":"C","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Conexão digital e economia das comunidades","steps":["O comando restringe a pergunta à rentabilidade.","O texto cita acesso a mercados, financiamento e cadeias de abastecimento maiores.","Esses recursos valorizam a economia local e os pequenos produtores, A, sem exigir uniformização dos modos de vida."],"alternatives":{"A":"A circulação e a comercialização da produção local podem ampliar renda e oportunidades.","B":"Projetos culturais não são o mecanismo econômico diretamente destacado no trecho.","C":"A rede amplia acesso comercial, mas não torna as comunidades criadoras das regras de mercado.","D":"Melhorar escolas não é a relação causal apresentada para a rentabilidade.","E":"A tecnologia não é descrita como padronização da qualificação de todos os trabalhadores."},"takeaway":"Use o comando para escolher entre benefícios possíveis e o benefício efetivamente explicado.","key":"humanas:H842","area":"humanas","year":2024,"number":67,"answer":"A","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Floresta e reciclagem de umidade","steps":["Árvores devolvem água à atmosfera por evapotranspiração; não criam água do nada.","O desmatamento reduz essa devolução de vapor e a reciclagem regional de umidade.","Com menor umidade disponível, pode diminuir a intensidade das chuvas convectivas, E."],"alternatives":{"A":"A relação direta dos textos não é uma redução da circulação dos ventos alísios.","B":"Retirar cobertura vegetal não fundamenta menor aquecimento do solo; pode aumentá-lo.","C":"Não há dados para inferir queda da temperatura média dos oceanos.","D":"O desmate não implica necessariamente redução do albedo; esse não é o elo hídrico cobrado.","E":"Menos evapotranspiração reduz a umidade que alimenta parte das chuvas regionais."},"takeaway":"Separe evapotranspiração, convecção e transporte de vapor sem tratar a floresta como fábrica de água.","key":"humanas:H446","area":"humanas","year":2024,"number":68,"answer":"E","subject":"Geografia","topic":"Climatologia e biomas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[25],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Respeito às capacidades das mulheres","steps":["A autora critica uma educação que prepara mulheres apenas para seduzir.","Ela pede respeito por capacidades, virtudes e racionalidade.","A reivindicação expressa é valorizar seu papel social, C; não há no excerto proposta específica de salário ou cargo."],"alternatives":{"A":"Recuperar uma participação política anterior não é a demanda formulada no trecho.","B":"Equiparação salarial é uma pauta possível, mas não aparece nesta argumentação.","C":"O reconhecimento das mulheres como criaturas humanas racionais amplia sua valorização social.","D":"A autora contesta a redução das mulheres ao sexo biológico, não pede aprofundá-la.","E":"O texto não delimita o reconhecimento à ocupação de cargos públicos."},"takeaway":"Não substitua a reivindicação textual por outra pauta legítima que você conhece.","key":"humanas:H731","area":"humanas","year":2024,"number":69,"answer":"C","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Objetos técnicos e circulação","steps":["Supermercados, portos e armazéns dependem de conexões e coordenação.","O texto apresenta objetos integrados em sistemas de transporte e abastecimento.","Sua finalidade comum é dinamizar fluxos de pessoas e mercadorias, E, não garantir distribuição de renda."],"alternatives":{"A":"A infraestrutura descrita apoia atividades econômicas, não visa desindustrializá-las.","B":"Não se discutem leis ou a retirada de regulação dos mercados.","C":"Pode haver concentração produtiva, mas a função comum dos objetos citados é conectar e fazer circular.","D":"Mais infraestrutura não produz automaticamente distribuição de renda.","E":"Redes e objetos coordenados intensificam circulação, acesso e articulação territorial."},"takeaway":"Em redes geográficas, relacione os nós materiais aos fluxos que eles permitem.","key":"humanas:H421","area":"humanas","year":2024,"number":70,"answer":"E","subject":"Geografia","topic":"Industrialização, trabalho e redes","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quem pressiona na negociação climática","steps":["Identifique a conferência promovida pela ONU e os compromissos entre países.","O trecho também destaca empresas e instituições organizadas fora do aparelho estatal.","A combinação corresponde a organismos supranacionais e sociedade civil, D; sociedade civil não se limita a movimentos populares."],"alternatives":{"A":"Os grupos mencionados nessa alternativa não são os agentes destacados no texto.","B":"Instituições militares e blocos econômicos não explicam a pressão empresarial citada.","C":"Cientistas são relevantes no tema, mas universidades não são o grupo descrito.","D":"A ONU articula a conferência; associações e empresas integram a pressão não estatal relatada.","E":"A demanda turística não aparece como motor da revisão da meta brasileira."},"takeaway":"Classifique os atores citados, sem trocar o texto por seu conhecimento geral sobre o tema.","key":"humanas:H302","area":"humanas","year":2024,"number":71,"answer":"D","subject":"Geografia","topic":"Geografia agrária e agropecuária","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma ética do cuidado diante da vulnerabilidade","steps":["O texto destaca assimetria de poder e vulnerabilidades que podem se acumular.","A pergunta solicita uma orientação ética interpessoal, não só punição jurídica.","Cuidado, proteção e valorização dos indivíduos respondem diretamente ao problema, A."],"alternatives":{"A":"A tríade reconhece a dignidade de quem está em relação desigual e requer apoio.","B":"Perdoar responsáveis não prioriza a proteção de quem sofre negligência ou violência.","C":"Cerceamento e controle não são uma ética centrada na dignidade e no cuidado.","D":"Leis e responsabilização importam, mas não substituem o foco interpessoal pedido.","E":"Fechar-se em si e ser indulgente com agentes não protege a pessoa vulnerabilizada."},"takeaway":"Diferencie cuidado e promoção de autonomia de tutela autoritária ou mera punição.","key":"humanas:H618","area":"humanas","year":2024,"number":72,"answer":"A","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[26],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Xilogravura transforma a apresentação do cordel","steps":["O problema inicial era a demora para produzir clichês em outras cidades.","Artesãos locais passam a talhar imagens na madeira disponível.","Muda a aparência e a produção visual das capas, isto é, a estética editorial, D, não necessariamente a narrativa dos versos."],"alternatives":{"A":"O suporte discutido é o folheto de cordel, não uma transformação do jornalismo.","B":"Alterar a imagem da capa não demonstra mudança na estrutura narrativa dos poemas.","C":"O foco não é uma expansão industrial regional em sentido amplo.","D":"A incorporação da xilogravura renova a linguagem visual da edição dos folhetos.","E":"O processo valoriza artesãos e cultura popular, não a conversão em cultura erudita."},"takeaway":"Pergunte se a técnica modifica o conteúdo, a apresentação ou a circulação de uma obra.","key":"humanas:H782","area":"humanas","year":2024,"number":73,"answer":"D","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma festa como patrimônio imaterial","steps":["O Círio envolve ritos, práticas, devoção e participação coletiva ao longo do tempo.","O patrimônio não se reduz aos edifícios ou aos objetos usados na festa.","Seu reconhecimento se sustenta no registro de bens culturais imateriais, B."],"alternatives":{"A":"Políticas locais podem apoiar a festa, mas não nomeiam a categoria patrimonial pertinente.","B":"Celebrações e saberes coletivos podem ser registrados como patrimônio de natureza imaterial.","C":"A festa não é apresentada como sítio arqueológico privado a ser tombado.","D":"Objetos sacros são apenas parte da celebração; a alternativa reduz o conjunto cultural.","E":"O reconhecimento patrimonial não depende de tornar uma manifestação cristã religião oficial."},"takeaway":"Diferencie registro de patrimônio imaterial de tombamento de bens materiais.","key":"humanas:H783","area":"humanas","year":2024,"number":74,"answer":"B","subject":"Sociologia","topic":"Cultura, identidade e diversidade","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Circulação intelectual com barreiras sociais","steps":["Salões aproximam escritores da elite; cafés são mais abertos.","Os espaços difundem debates iluministas, mas não integram todos os pensadores em condições iguais.","A formulação reúne os dois aspectos: segregação de pensadores e circulação de ideias, A."],"alternatives":{"A":"A alternativa combina a diferenciação social dos espaços com sua função de debate.","B":"O texto não descreve perseguição à nobreza; certos pensadores procuram aproximar-se dela.","C":"Não apresenta proibição geral de mulheres nem rejeição de poetisas como função central.","D":"Os espaços promovem circulação intelectual; não se definem por censura a cronistas.","E":"A ampliação do comércio urbano não é a contribuição intelectual analisada."},"takeaway":"Uma transformação pode ampliar o debate sem eliminar as hierarquias sociais.","key":"humanas:H212","area":"humanas","year":2024,"number":75,"answer":"A","subject":"História Geral","topic":"Iluminismo e revoluções burguesas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Rizoma e conexões plurais","steps":["O rizoma conecta pontos diferentes sem um centro organizador obrigatório.","O texto o contrapõe à hierarquia e a ligações preestabelecidas.","O elemento compatível é a pluralidade de interações, E, não a uniformidade ou um controle central."],"alternatives":{"A":"Uma estrutura fixa contraria a abertura das conexões descritas.","B":"Reduzir tudo a dois polos é incompatível com a multiplicidade das conexões.","C":"Controle homogêneo pressupõe uma ordenação que o conceito procura superar.","D":"Interagir não exige concordar: uniformidade de opiniões não caracteriza rizoma.","E":"Relações múltiplas e não subordinadas a um único centro correspondem à descrição."},"takeaway":"Em conceitos metafóricos, enumere os traços dados pelo próprio texto antes de extrapolar.","key":"humanas:H695","area":"humanas","year":2024,"number":76,"answer":"E","subject":"Filosofia","topic":"Filosofia contemporânea","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[27],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Uma imagem turística selecionada do Brasil","steps":["As capas associam o país a Carmen Miranda, vestimentas e tipos regionais.","Produzidas pelo DIP, constroem uma imagem reconhecível e atraente para divulgação externa.","O conjunto evidencia estereótipos da cultura nacional, A; as imagens não mostram a industrialização."],"alternatives":{"A":"Tipos e símbolos selecionados condensam a diversidade nacional numa representação turística.","B":"As capas não denunciam relações de exploração da população pobre.","C":"Representações podem ser criticamente discutidas, mas a evidência pedida é a estereotipação cultural.","D":"Saber que o DIP censurava não faz da censura o conteúdo visível dessas capas.","E":"As imagens destacam tipos culturais, não fábricas ou um projeto industrial."},"takeaway":"Não responda só com o que sabe sobre a instituição: observe o documento efetivamente mostrado.","key":"humanas:H102","area":"humanas","year":2024,"number":77,"answer":"A","subject":"História do Brasil","topic":"Era Vargas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Regra universal de respeito ao outro","steps":["A regra propõe um padrão de conduta que não depende da vantagem de uma ocasião.","Entre as opções, o gabarito B aproxima essa exigência moral geral do imperativo categórico.","A aproximação não torna idênticas a regra de ouro e a formulação kantiana: esta exige universalização racional, não apenas preferência pessoal."],"alternatives":{"A":"Uma doutrina teleológica fundamenta a ação num fim; esse não é o critério exposto.","B":"É a opção que melhor expressa uma obrigação moral geral, sem cálculo de benefícios.","C":"O utilitarismo avalia resultados e bem-estar agregado, ausentes na formulação citada.","D":"Secularização trata de mudanças no papel social da religião, não dessa regra de conduta.","E":"A regra não autoriza agir conforme a consequência mais vantajosa."},"takeaway":"Na comparação com Kant, lembre que universalizar uma máxima não é simplesmente projetar seu gosto nos outros.","key":"humanas:H619","area":"humanas","year":2024,"number":78,"answer":"B","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Superar a exclusão de refugiados","steps":["A fronteira descrita é também social: admissão legal não basta para garantir pertencimento.","Vulnerabilidade e incerteza exigem acesso efetivo a direitos, trabalho e serviços.","A política pertinente é integração socioeconômica, E, preservando diferenças culturais."],"alternatives":{"A":"Planejamento familiar não enfrenta diretamente a exclusão e a insegurança de refugiados.","B":"Segregação mantém ou aprofunda a fronteira entre admitidos e rejeitados.","C":"Acolher não exige apagar culturas ou produzir uma sociedade homogênea.","D":"Diferenciar direitos por raça ou etnia reforçaria a exclusão criticada.","E":"Acesso a condições materiais e participação social enfrenta a vulnerabilidade descrita."},"takeaway":"Fronteiras podem ser políticas, jurídicas e sociais, não apenas linhas territoriais.","key":"humanas:H486","area":"humanas","year":2024,"number":79,"answer":"E","subject":"Geografia","topic":"Demografia e migrações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[28],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Novelas e apropriação cultural","steps":["Na Rússia, as novelas mobilizam audiência e até alteram rotinas.","Em Angola, inspiram nomes de lugares, moda e comportamentos.","O elo comum é a incorporação cultural de costumes da teledramaturgia estrangeira, A."],"alternatives":{"A":"Os exemplos mostram práticas e referências culturais apropriadas por públicos estrangeiros.","B":"Influenciar moda não prova importação de roupas de estilistas famosos.","C":"Distâncias físicas ou ideológicas não são o fenômeno demonstrado pelos relatos.","D":"Não se trata da adaptação de valores de povos tradicionais nesses dois países.","E":"O consumo das novelas não demonstra adoção de sistemas políticos democráticos."},"takeaway":"Diferencie circulação cultural de conclusões econômicas e políticas não sustentadas pelo documento.","key":"humanas:H843","area":"humanas","year":2024,"number":80,"answer":"A","subject":"Sociologia","topic":"Comunicação, consumo e tecnologia","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quilombos e direitos constitucionais","steps":["O texto reconhece patrimônio territorial e cultural historicamente pouco atendido pelo Estado.","A Constituição de 1988 passa a fundamentar reconhecimento e direitos de comunidades quilombolas, incluindo direitos territoriais.","A categoria abrangente das opções é políticas de inserção social, D, não assimilação cultural."],"alternatives":{"A":"A questão não apresenta natalidade ou organização reprodutiva como alvo da política.","B":"A proteção constitucional não exige mudar a religião das comunidades.","C":"Moradia sustentável não resume o reconhecimento territorial e cultural mencionado.","D":"Reconhecimento e garantia de direitos enfrentam a exclusão histórica dessas comunidades.","E":"Homogeneizar a educação apagando diferenças contraria o reconhecimento da diversidade."},"takeaway":"Direitos territoriais quilombolas articulam cidadania, memória e condições de reprodução cultural.","key":"humanas:H732","area":"humanas","year":2024,"number":81,"answer":"D","subject":"Sociologia","topic":"Cidadania, direitos e movimentos sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Do caso observado à regra geral","steps":["O peru reúne vários episódios particulares em diferentes condições.","A partir da repetição, afirma que sempre será alimentado às nove.","Isso é indução, C: a conclusão ultrapassa os casos observados e não é logicamente garantida por eles."],"alternatives":{"A":"O personagem não recomenda uma ação prática; formula uma regularidade geral.","B":"Buscar confirmações não nomeia o tipo de inferência realizado a partir dos casos.","C":"A passagem de observações particulares para uma afirmação universal caracteriza indução.","D":"Observações finitas não demonstram de modo indubitável uma lei para todos os dias.","E":"Não há transferência de propriedades entre casos semelhantes por comparação analógica."},"takeaway":"Na indução, muitas confirmações aumentam apoio, mas não tornam a conclusão universal necessária.","key":"humanas:H665","area":"humanas","year":2024,"number":82,"answer":"C","subject":"Filosofia","topic":"Filosofia moderna: razão, ciência e conhecimento","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mapas como instrumentos de poder","steps":["O autor realça a seleção do que interessa a uma minoria dominante.","Conhecer, registrar e representar territórios pode facilitar seu controle.","A cartografia aparece a serviço da sustentação de hegemonias territoriais, E; o texto não diz que todo mapa só pode ter essa função."],"alternatives":{"A":"Preservar a natureza é um uso possível de mapas, mas não o uso destacado.","B":"O trecho prioriza grupos dominantes, não a emancipação de grupos marginalizados.","C":"Não apresenta valorização de culturas reprimidas como finalidade central.","D":"Os mapas descritos sustentam relações de poder, em vez de necessariamente invertê-las.","E":"A seleção de informações territoriais favorece dominação e manutenção de hegemonias."},"takeaway":"Representações cartográficas envolvem escolhas de informação e interesses sociais.","key":"humanas:H555","area":"humanas","year":2024,"number":83,"answer":"E","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[29],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Regatões conectam pessoas e lugares","steps":["O comércio circula pelos rios entre comunidades diversas.","A relação envolve quilombolas, indígenas, produtores e outros comerciantes.","Além de abastecer, constrói redes de sociabilidade no interior, D, articulando encontros e trocas."],"alternatives":{"A":"O texto não descreve organização de fuga nem atribui essa função ao comerciante.","B":"Não associa o regatão à criação de postos de trabalho nos seringais.","C":"A variedade de mercadorias não demonstra divulgação de receitas farmacêuticas.","D":"A circulação comercial articula grupos e comunidades em relações sociais duradouras.","E":"O foco é abastecimento e relações sociais, não ampliação de equipamentos de lazer."},"takeaway":"Comércio e transporte também criam relações sociais: não se limitam a movimentar objetos.","key":"humanas:H422","area":"humanas","year":2024,"number":84,"answer":"D","subject":"Geografia","topic":"Industrialização, trabalho e redes","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Denúncia pública da repressão argentina","steps":["As mães ocupam a praça e desafiam o aparato militar.","Sua persistência torna internacionalmente visíveis desaparecimentos e repressão estatal.","O problema exposto é a violação de direitos humanos, A, não apenas uma controvérsia abstrata sobre democracia."],"alternatives":{"A":"A repressão e os desaparecimentos forçados ferem direitos humanos e motivam a denúncia.","B":"O texto não delimita o problema à insegurança de jovens em periferias.","C":"Não se trata de violência no âmbito doméstico, mas da ação repressiva do Estado.","D":"A desigualdade social não é o problema específico denunciado pelo movimento.","E":"A alternativa é menos precisa e não nomeia a violência estatal destacada."},"takeaway":"Associe movimentos sociais a suas reivindicações concretas e ao agente da violência denunciada.","key":"humanas:H253","area":"humanas","year":2024,"number":85,"answer":"A","subject":"História Geral","topic":"Guerra Fria e mundo contemporâneo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As imagens mostram a construção do litoral","steps":["Compare Dubai em 2000 e em 2020.","Na segunda imagem aparecem ilhas artificiais e expansão de estruturas construídas na costa.","A intervenção humana materializa artificialização do espaço geográfico, D; não muda fronteiras nacionais."],"alternatives":{"A":"O documento evidencia obras e transformação espacial, não proteção de lugares de memória.","B":"A região já é árida; a expansão de ilhas não demonstra um processo de desertificação.","C":"Modificar o litoral por aterros não implica redefinir a fronteira entre Estados.","D":"Ilhas e estruturas construídas mostram transformação técnica do ambiente.","E":"Duas imagens locais não demonstram mudança na dinâmica macroclimática do planeta."},"takeaway":"Em imagens de satélite, descreva primeiro a mudança visível e só depois proponha uma explicação.","key":"humanas:H556","area":"humanas","year":2024,"number":86,"answer":"D","subject":"Geografia","topic":"Cartografia, paisagem e tecnologias geográficas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[30],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Quem é o titular do poder democrático","steps":["A pergunta do autor é quem deve mandar, não qual o tamanho do Estado.","A resposta atribui o poder à coletividade dos cidadãos.","Esse fundamento é a soberania popular, A: a legitimidade do mando deriva do povo."],"alternatives":{"A":"A coletividade dos cidadãos é apresentada como titular legítima do poder público.","B":"Divisão de classes é uma característica social, não o fundamento democrático indicado.","C":"Acumular capital não confere a titularidade democrática do poder.","D":"A defesa da propriedade não responde a quem cabe governar.","E":"A questão não exige uma administração centralizada, mas participação coletiva."},"takeaway":"Separe titularidade do poder, limites do poder e forma administrativa do Estado.","key":"humanas:H620","area":"humanas","year":2024,"number":87,"answer":"A","subject":"Filosofia","topic":"Ética e filosofia política","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O veto mostra desigualdade de poder","steps":["O Conselho tem quinze membros, mas apenas cinco são permanentes e possuem veto.","Logo, os membros não dispõem dos mesmos instrumentos de decisão.","A estrutura expressa assimetria política, B; ter direito de veto permite bloquear decisões mesmo sem consenso geral."],"alternatives":{"A":"O texto não demonstra igualdade de capacidades militares entre os países.","B":"Prerrogativas exclusivas produzem pesos políticos diferentes dentro do organismo.","C":"A possibilidade de veto revela que o consenso não é uma condição sempre alcançada.","D":"Não há demonstração de equilíbrio entre todos os participantes.","E":"Participar de uma organização internacional não implica compartilhar igualmente soberania ou poder."},"takeaway":"Compare direitos formais e prerrogativas especiais para identificar assimetrias institucionais.","key":"humanas:H357","area":"humanas","year":2024,"number":89,"answer":"B","subject":"Geografia","topic":"Geopolítica e globalização","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O trabalho humano é necessário e reprimido","steps":["A fábrica depende de iniciativa, interpretação e adaptação dos trabalhadores.","Ao mesmo tempo, sua organização tenta reduzi-los a executores mecânicos.","A contradição corresponde à alienação decorrente da organização do trabalho, C: precisa da atividade humana enquanto a subordina e desumaniza."],"alternatives":{"A":"Não se discute principalmente o envelhecimento de máquinas ou a obsolescência tecnológica.","B":"Administrar conflitos não nomeia a contradição entre atividade humana e redução a peça.","C":"A organização tenta retirar autonomia e controle de quem realiza o trabalho, embora dependa deles.","D":"O autor não afirma igualdade social na apropriação da riqueza produzida.","E":"A opção descreve fortalecimento da autonomia, quando o texto destaca sua restrição."},"takeaway":"Procure os dois polos da contradição: aquilo de que o sistema depende e aquilo que tenta negar.","key":"humanas:H759","area":"humanas","year":2024,"number":90,"answer":"C","subject":"Sociologia","topic":"Trabalho, capitalismo e desigualdades","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2024_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"humanas/gab_2024.pdf","sha256":"673d3d060156d6ad610ecf96c3dd0b8c61f361e16c57860c4ca5b5fecc8be050","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/humanas/prova_2024.pdf","sourceExamPages":[31],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
